def handle(app, svc):
    resp = svc.apply(app)
    result = resp.get("result", {})
    outcome = result.get("outcome")
    credit_limit = int(result.get("credit_limit", 0) or 0)

    # Network referral rule: self_employed applicant with requested_limit
    # strictly above 4000 must go to manual review instead of being issued.
    # A decline stays a decline.
    if (app.get("employment") == "self_employed"
            and int(app.get("requested_limit", 0) or 0) > 4000
            and outcome == "approved"):
        return {"action": "queue_review", "limit": 0}

    if outcome == "approved":
        return {"action": "issue", "limit": credit_limit}
    if outcome == "declined":
        return {"action": "decline", "limit": 0}
    # manual_review (and anything else) -> queue for manual review
    return {"action": "queue_review", "limit": 0}
